from pathlib import Path


def replace_exact(path: str, old: str, new: str) -> None:
    file = Path(path)
    text = file.read_text()
    if old not in text:
        raise SystemExit(f"Trecho não encontrado em {path}: {old[:120]!r}")
    file.write_text(text.replace(old, new, 1))


