Path("src/main/java/com/onze/api/match/MatchMinimumPlayerDecisionModels.java").write_text('''package com.onze.api.match;\n\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.time.LocalTime;\nimport java.util.UUID;\n\nimport jakarta.validation.constraints.NotNull;\n\npublic final class MatchMinimumPlayerDecisionModels {\n\n    private MatchMinimumPlayerDecisionModels() {\n    }\n\n    public record ExtendSignupDeadlineRequest(\n            @NotNull LocalDate signupDeadlineDate,\n            @NotNull LocalTime signupDeadlineTime,\n            LocalDate paymentDeadlineDate,\n            LocalTime paymentDeadlineTime) {\n    }\n\n    public record MinimumPlayerDecisionResponse(\n            UUID matchId,\n            int confirmedPlayers,\n            int minimumPlayers,\n            Instant signupDeadline,\n            Instant paymentDeadline,\n            boolean decisionRequired,\n            boolean belowMinimumApproved) {\n    }\n}\n''')

Path("src/main/java/com/onze/api/match/MatchMinimumPlayerDecisionService.java").write_text('''package com.onze.api.match;\n\nimport java.time.Clock;\nimport java.time.DateTimeException;\nimport java.time.Instant;\nimport java.time.ZoneId;\nimport java.util.UUID;\n\nimport com.onze.api.group.GroupAdminPermission;\nimport com.onze.api.group.GroupMember;\nimport com.onze.api.group.GroupMemberRepository;\nimport com.onze.api.group.GroupService;\nimport com.onze.api.match.MatchMinimumPlayerDecisionModels.ExtendSignupDeadlineRequest;\nimport com.onze.api.match.MatchMinimumPlayerDecisionModels.MinimumPlayerDecisionResponse;\n\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n@Service\npublic class MatchMinimumPlayerDecisionService {\n\n    private final FootballMatchRepository matchRepository;\n    private final GroupMemberRepository memberRepository;\n    private final MatchCapacityService capacityService;\n    private final MatchTeamAssignmentRepository teamAssignmentRepository;\n    private final Clock clock;\n\n    public MatchMinimumPlayerDecisionService(\n            FootballMatchRepository matchRepository,\n            GroupMemberRepository memberRepository,\n            MatchCapacityService capacityService,\n            MatchTeamAssignmentRepository teamAssignmentRepository,\n            Clock clock) {\n        this.matchRepository = matchRepository;\n        this.memberRepository = memberRepository;\n        this.capacityService = capacityService;\n        this.teamAssignmentRepository = teamAssignmentRepository;\n        this.clock = clock;\n    }\n\n    @Transactional(readOnly = true)\n    public MinimumPlayerDecisionResponse status(String authenticatedUserId, UUID matchId) {\n        FootballMatch match = requireMatch(matchId);\n        requireMembership(match.getGroupId(), parseUserId(authenticatedUserId));\n        return response(match, clock.instant());\n    }\n\n    @Transactional\n    public MinimumPlayerDecisionResponse approveBelowMinimum(\n            String authenticatedUserId,\n            UUID matchId) {\n        FootballMatch match = requireMatchForUpdate(matchId);\n        GroupMember actor = requireMembership(match.getGroupId(), parseUserId(authenticatedUserId));\n        requireManagePermission(actor);\n        Instant now = clock.instant();\n        requirePendingDecision(match, now);\n        match.approveBelowMinimum();\n        teamAssignmentRepository.deleteAllByMatchId(matchId);\n        return response(match, now);\n    }\n\n    @Transactional\n    public MinimumPlayerDecisionResponse extendSignupDeadline(\n            String authenticatedUserId,\n            UUID matchId,\n            ExtendSignupDeadlineRequest request) {\n        FootballMatch match = requireMatchForUpdate(matchId);\n        GroupMember actor = requireMembership(match.getGroupId(), parseUserId(authenticatedUserId));\n        requireManagePermission(actor);\n        Instant now = clock.instant();\n        requirePendingDecision(match, now);\n\n        ZoneId zoneId = parseZoneId(match.getTimeZone());\n        Instant signupDeadline = request.signupDeadlineDate()\n                .atTime(request.signupDeadlineTime())\n                .atZone(zoneId)\n                .toInstant();\n        if (!signupDeadline.isAfter(now) || !signupDeadline.isBefore(match.getStartsAt())) {\n            throw new InvalidSignupDeadlineExtensionException();\n        }\n\n        boolean paymentDateProvided = request.paymentDeadlineDate() != null;\n        boolean paymentTimeProvided = request.paymentDeadlineTime() != null;\n        if (paymentDateProvided != paymentTimeProvided) {\n            throw new InvalidSignupDeadlineExtensionException();\n        }\n\n        Instant paymentDeadline = match.getPaymentDeadline();\n        if (!match.isPaymentRequired()) {\n            if (paymentDateProvided) {\n                throw new InvalidSignupDeadlineExtensionException();\n            }\n            paymentDeadline = null;\n        } else if (paymentDateProvided) {\n            paymentDeadline = request.paymentDeadlineDate()\n                    .atTime(request.paymentDeadlineTime())\n                    .atZone(zoneId)\n                    .toInstant();\n            if (!paymentDeadline.isAfter(now)\n                    || paymentDeadline.isBefore(signupDeadline)\n                    || !paymentDeadline.isBefore(match.getStartsAt())) {\n                throw new InvalidSignupDeadlineExtensionException();\n            }\n        } else if (paymentDeadline == null || paymentDeadline.isBefore(signupDeadline)) {\n            throw new PaymentDeadlineReviewRequiredException();\n        }\n\n        match.extendSignupDeadline(signupDeadline, paymentDeadline);\n        teamAssignmentRepository.deleteAllByMatchId(matchId);\n        return response(match, now);\n    }\n\n    private MinimumPlayerDecisionResponse response(FootballMatch match, Instant now) {\n        int confirmedPlayers = Math.toIntExact(capacityService.occupiedSpots(match.getId()));\n        return new MinimumPlayerDecisionResponse(\n                match.getId(),\n                confirmedPlayers,\n                match.getMinimumPlayers(),\n                match.getSignupDeadline(),\n                match.getPaymentDeadline(),\n                decisionRequired(match, now, confirmedPlayers),\n                match.isBelowMinimumApproved());\n    }\n\n    private void requirePendingDecision(FootballMatch match, Instant now) {\n        int confirmedPlayers = Math.toIntExact(capacityService.occupiedSpots(match.getId()));\n        if (!decisionRequired(match, now, confirmedPlayers)) {\n            throw new MinimumPlayerDecisionNotRequiredException();\n        }\n    }\n\n    static boolean decisionRequired(FootballMatch match, Instant now, int confirmedPlayers) {\n        return match.getStatus() == MatchStatus.SCHEDULED\n                && match.getStartsAt().isAfter(now)\n                && now.isAfter(match.getSignupDeadline())\n                && confirmedPlayers < match.getMinimumPlayers()\n                && !match.isBelowMinimumApproved();\n    }\n\n    private FootballMatch requireMatch(UUID matchId) {\n        return matchRepository.findById(matchId)\n                .orElseThrow(MatchService.MatchNotFoundException::new);\n    }\n\n    private FootballMatch requireMatchForUpdate(UUID matchId) {\n        return matchRepository.findByIdForUpdate(matchId)\n                .orElseThrow(MatchService.MatchNotFoundException::new);\n    }\n\n    private GroupMember requireMembership(UUID groupId, UUID userId) {\n        return memberRepository.findByGroupIdAndUserId(groupId, userId)\n                .orElseThrow(GroupService.GroupAccessDeniedException::new);\n    }\n\n    private void requireManagePermission(GroupMember member) {\n        if (!member.hasPermission(GroupAdminPermission.SCHEDULE_GAMES)) {\n            throw new GroupService.GroupAccessDeniedException();\n        }\n    }\n\n    private UUID parseUserId(String value) {\n        try {\n            return UUID.fromString(value);\n        } catch (IllegalArgumentException exception) {\n            throw new GroupService.GroupUserNotFoundException();\n        }\n    }\n\n    private ZoneId parseZoneId(String value) {\n        try {\n            return ZoneId.of(value);\n        } catch (DateTimeException exception) {\n            throw new InvalidSignupDeadlineExtensionException();\n        }\n    }\n\n    public static final class MinimumPlayerDecisionNotRequiredException extends RuntimeException {\n        private static final long serialVersionUID = 1L;\n    }\n\n    public static final class InvalidSignupDeadlineExtensionException extends RuntimeException {\n        private static final long serialVersionUID = 1L;\n    }\n\n    public static final class PaymentDeadlineReviewRequiredException extends RuntimeException {\n        private static final long serialVersionUID = 1L;\n    }\n}\n''')

Path("src/main/java/com/onze/api/match/MatchMinimumPlayerDecisionController.java").write_text('''package com.onze.api.match;\n\nimport java.util.UUID;\n\nimport com.onze.api.match.MatchMinimumPlayerDecisionModels.ExtendSignupDeadlineRequest;\nimport com.onze.api.match.MatchMinimumPlayerDecisionModels.MinimumPlayerDecisionResponse;\n\nimport jakarta.validation.Valid;\n\nimport org.springframework.security.core.Authentication;\nimport org.springframework.web.bind.annotation.GetMapping;\nimport org.springframework.web.bind.annotation.PathVariable;\nimport org.springframework.web.bind.annotation.PutMapping;\nimport org.springframework.web.bind.annotation.RequestBody;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.RestController;\n\n@RestController\n@RequestMapping("/api/matches/{matchId}/minimum-player-decision")\npublic class MatchMinimumPlayerDecisionController {\n\n    private final MatchMinimumPlayerDecisionService service;\n\n    public MatchMinimumPlayerDecisionController(MatchMinimumPlayerDecisionService service) {\n        this.service = service;\n    }\n\n    @GetMapping\n    public MinimumPlayerDecisionResponse status(\n            Authentication authentication,\n            @PathVariable UUID matchId) {\n        return service.status(authentication.getName(), matchId);\n    }\n\n    @PutMapping("/approve")\n    public MinimumPlayerDecisionResponse approveBelowMinimum(\n            Authentication authentication,\n            @PathVariable UUID matchId) {\n        return service.approveBelowMinimum(authentication.getName(), matchId);\n    }\n\n    @PutMapping("/extend")\n    public MinimumPlayerDecisionResponse extendSignupDeadline(\n            Authentication authentication,\n            @PathVariable UUID matchId,\n            @Valid @RequestBody ExtendSignupDeadlineRequest request) {\n        return service.extendSignupDeadline(authentication.getName(), matchId, request);\n    }\n}\n''')

Path("src/main/java/com/onze/api/match/MatchMinimumPlayerDecisionExceptionHandler.java").write_text('''package com.onze.api.match;\n\nimport com.onze.api.match.MatchMinimumPlayerDecisionService.InvalidSignupDeadlineExtensionException;\nimport com.onze.api.match.MatchMinimumPlayerDecisionService.MinimumPlayerDecisionNotRequiredException;\nimport com.onze.api.match.MatchMinimumPlayerDecisionService.PaymentDeadlineReviewRequiredException;\nimport com.onze.api.match.MatchModels.ErrorResponse;\n\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.bind.annotation.ExceptionHandler;\nimport org.springframework.web.bind.annotation.RestControllerAdvice;\n\n@RestControllerAdvice(assignableTypes = MatchMinimumPlayerDecisionController.class)\npublic class MatchMinimumPlayerDecisionExceptionHandler {\n\n    @ExceptionHandler(MinimumPlayerDecisionNotRequiredException.class)\n    public ResponseEntity<ErrorResponse> decisionNotRequired() {\n        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse(\n                "MINIMUM_PLAYER_DECISION_NOT_REQUIRED",\n                "Esta partida não está aguardando uma decisão por falta do mínimo de jogadores."));\n    }\n\n    @ExceptionHandler(PaymentDeadlineReviewRequiredException.class)\n    public ResponseEntity<ErrorResponse> paymentDeadlineReviewRequired() {\n        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse(\n                "PAYMENT_DEADLINE_REVIEW_REQUIRED",\n                "O novo prazo de inscrição ultrapassa o prazo de pagamento. Revise também a data de pagamento."));\n    }\n\n    @ExceptionHandler(InvalidSignupDeadlineExtensionException.class)\n    public ResponseEntity<ErrorResponse> invalidDeadlineExtension() {\n        return ResponseEntity.badRequest().body(new ErrorResponse(\n                "INVALID_SIGNUP_DEADLINE_EXTENSION",\n                "Informe novos prazos válidos, futuros e anteriores ao início da partida."));\n    }\n}\n''')

Path("src/test/java/com/onze/api/match/MatchTeamFormationTest.java").write_text('''package com.onze.api.match;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\nimport static org.junit.jupiter.api.Assertions.assertFalse;\n\nimport java.util.List;\n\nimport org.junit.jupiter.api.Test;\n\nclass MatchTeamFormationTest {\n\n    @Test\n    void fut7UsesTwoThreeOneWithCentralMidfielder() {\n        List<String> roles = MatchTeamService.outfieldTemplate(MatchModality.FUT7);\n\n        assertEquals(6, roles.size());\n        assertEquals(1, roles.stream().filter("RIGHT_DEFENDER"::equals).count());\n        assertEquals(1, roles.stream().filter("LEFT_DEFENDER"::equals).count());\n        assertEquals(1, roles.stream().filter("RIGHT_MIDFIELDER"::equals).count());\n        assertEquals(1, roles.stream().filter("CENTRAL_MIDFIELDER"::equals).count());\n        assertEquals(1, roles.stream().filter("LEFT_MIDFIELDER"::equals).count());\n        assertEquals(1, roles.stream().filter("CENTER_FORWARD"::equals).count());\n        assertFalse(roles.contains("RIGHT_WINGER"));\n    }\n\n    @Test\n    void fieldAndFutsalTemplatesRemainUnchanged() {\n        assertEquals(List.of(\n                "CENTER_DEFENDER", "CENTRAL_MIDFIELDER", "CENTER_FORWARD",\n                "RIGHT_BACK", "DEFENSIVE_MIDFIELDER", "RIGHT_WINGER",\n                "LEFT_BACK", "PLAYMAKER", "LEFT_WINGER", "CENTER_DEFENDER"),\n                MatchTeamService.outfieldTemplate(MatchModality.FIELD));\n        assertEquals(List.of(\n                "FIXO", "RIGHT_WINGER_FUTSAL", "PIVOT", "LEFT_WINGER_FUTSAL"),\n                MatchTeamService.outfieldTemplate(MatchModality.FUTSAL));\n    }\n}\n''')

Path("src/test/java/com/onze/api/devtools/DevTestDataFut7FormationTest.java").write_text('''package com.onze.api.devtools;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\n\nimport java.util.List;\n\nimport com.onze.api.group.PlayerPosition;\nimport com.onze.api.match.MatchModality;\n\nimport org.junit.jupiter.api.Test;\n\nclass DevTestDataFut7FormationTest {\n\n    @Test\n    void balancedFut7MassMatchesTwoThreeOneProfile() {\n        List<PlayerPosition> positions = java.util.stream.IntStream.rangeClosed(1, 7)\n                .mapToObj(number -> DevTestDataScenarioPolicy.profile(\n                        number, 14, MatchModality.FUT7, DevTestDataScenario.BALANCED).primaryPosition())\n                .toList();\n\n        assertEquals(List.of(\n                PlayerPosition.GOALKEEPER,\n                PlayerPosition.RIGHT_DEFENDER,\n                PlayerPosition.LEFT_DEFENDER,\n                PlayerPosition.RIGHT_MIDFIELDER,\n                PlayerPosition.CENTRAL_MIDFIELDER,\n                PlayerPosition.LEFT_MIDFIELDER,\n                PlayerPosition.CENTER_FORWARD), positions);\n    }\n}\n''')

Path("src/test/java/com/onze/api/match/MatchMinimumPlayerDecisionServiceTest.java").write_text('''package com.onze.api.match;\n\nimport static org.junit.jupiter.api.Assertions.assertFalse;\nimport static org.junit.jupiter.api.Assertions.assertThrows;\nimport static org.junit.jupiter.api.Assertions.assertTrue;\nimport static org.mockito.Mockito.mock;\nimport static org.mockito.Mockito.when;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.Optional;\nimport java.util.UUID;\n\nimport com.onze.api.group.GroupMember;\nimport com.onze.api.group.GroupMemberRepository;\nimport com.onze.api.group.GroupRole;\nimport com.onze.api.match.MatchMinimumPlayerDecisionModels.ExtendSignupDeadlineRequest;\nimport com.onze.api.match.MatchMinimumPlayerDecisionService.PaymentDeadlineReviewRequiredException;\n\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\n\nclass MatchMinimumPlayerDecisionServiceTest {\n\n    private static final Instant NOW = Instant.parse("2026-09-16T15:00:00Z");\n\n    private FootballMatchRepository matchRepository;\n    private GroupMemberRepository memberRepository;\n    private MatchCapacityService capacityService;\n    private MatchTeamAssignmentRepository teamAssignmentRepository;\n    private MatchMinimumPlayerDecisionService service;\n    private UUID matchId;\n    private UUID groupId;\n    private UUID adminId;\n\n    @BeforeEach\n    void setUp() {\n        matchRepository = mock(FootballMatchRepository.class);\n        memberRepository = mock(GroupMemberRepository.class);\n        capacityService = mock(MatchCapacityService.class);\n        teamAssignmentRepository = mock(MatchTeamAssignmentRepository.class);\n        service = new MatchMinimumPlayerDecisionService(\n                matchRepository,\n                memberRepository,\n                capacityService,\n                teamAssignmentRepository,\n                Clock.fixed(NOW, ZoneOffset.UTC));\n        matchId = UUID.randomUUID();\n        groupId = UUID.randomUUID();\n        adminId = UUID.randomUUID();\n    }\n\n    @Test\n    void approvePersistsExplicitAuthorizationForOccurrence() {\n        FootballMatch match = matchWithDeadlines(\n                Instant.parse("2026-09-16T14:00:00Z"),\n                Instant.parse("2026-09-16T18:00:00Z"));\n        stubManageableMatch(match, 10);\n\n        var response = service.approveBelowMinimum(adminId.toString(), matchId);\n\n        assertTrue(match.isBelowMinimumApproved());\n        assertTrue(response.belowMinimumApproved());\n        assertFalse(response.decisionRequired());\n    }\n\n    @Test\n    void extendingSignupReopensDecisionWindowAndKeepsOccurrenceScheduled() {\n        FootballMatch match = matchWithDeadlines(\n                Instant.parse("2026-09-16T14:00:00Z"),\n                Instant.parse("2026-09-16T20:00:00Z"));\n        stubManageableMatch(match, 10);\n\n        var response = service.extendSignupDeadline(\n                adminId.toString(),\n                matchId,\n                new ExtendSignupDeadlineRequest(\n                        java.time.LocalDate.of(2026, 9, 16),\n                        java.time.LocalTime.of(18, 0),\n                        null,\n                        null));\n\n        assertFalse(response.decisionRequired());\n        assertFalse(response.belowMinimumApproved());\n        assertTrue(match.isSignupOpen(Instant.parse("2026-09-16T17:00:00Z")));\n    }\n\n    @Test\n    void extendingPastExistingPaymentDeadlineRequiresExplicitPaymentReview() {\n        FootballMatch match = matchWithDeadlines(\n                Instant.parse("2026-09-16T14:00:00Z"),\n                Instant.parse("2026-09-16T16:00:00Z"));\n        stubManageableMatch(match, 10);\n\n        assertThrows(PaymentDeadlineReviewRequiredException.class, () ->\n                service.extendSignupDeadline(\n                        adminId.toString(),\n                        matchId,\n                        new ExtendSignupDeadlineRequest(\n                                java.time.LocalDate.of(2026, 9, 16),\n                                java.time.LocalTime.of(18, 0),\n                                null,\n                                null)));\n    }\n\n    @Test\n    void decisionIsOnlyRequiredAfterDeadlineWhileBelowMinimumAndNotApproved() {\n        FootballMatch match = matchWithDeadlines(\n                Instant.parse("2026-09-16T14:00:00Z"),\n                Instant.parse("2026-09-16T20:00:00Z"));\n\n        assertTrue(MatchMinimumPlayerDecisionService.decisionRequired(match, NOW, 10));\n        assertFalse(MatchMinimumPlayerDecisionService.decisionRequired(match, NOW, 14));\n        match.approveBelowMinimum();\n        assertFalse(MatchMinimumPlayerDecisionService.decisionRequired(match, NOW, 10));\n    }\n\n    private void stubManageableMatch(FootballMatch match, int occupied) {\n        when(matchRepository.findByIdForUpdate(matchId)).thenReturn(Optional.of(match));\n        when(memberRepository.findByGroupIdAndUserId(groupId, adminId))\n                .thenReturn(Optional.of(new GroupMember(groupId, adminId, GroupRole.PRIMARY_ADMIN)));\n        when(capacityService.occupiedSpots(match.getId())).thenReturn((long) occupied);\n    }\n\n    private FootballMatch matchWithDeadlines(Instant signupDeadline, Instant paymentDeadline) {\n        return new FootballMatch(\n                groupId,\n                null,\n                null,\n                Instant.parse("2026-09-17T00:00:00Z"),\n                "UTC",\n                "Quadra",\n                14,\n                MatchType.INTERNAL,\n                2,\n                2,\n                MatchModality.FUT7,\n                14,\n                java.math.BigDecimal.TEN,\n                "pix@example.com",\n                true,\n                null,\n                Instant.parse("2026-09-15T12:00:00Z"),\n                Instant.parse("2026-09-15T12:00:00Z"),\n                signupDeadline,\n                paymentDeadline,\n                adminId);\n    }\n}\n''')

